contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 seedAmount, uint256 transferAmount, address to) public {
        require(to != address(this) && to != address(0));
        require(seedAmount <= 1000000e18);

        // Seed this contract's balance via the airdrop (one call per top-level statement).
        c.getTokens();
        uint256 bal = c.balanceOf(address(this));

        if (transferAmount > bal) {
            bool reverted;
            // top-level call via try requires it not be nested; use separate try at top level
            try c.transfer(to, transferAmount) { reverted = false; } catch { reverted = true; }
            assert(reverted);
            assert(c.balanceOf(address(this)) == bal);
        } else {
            bool ok;
            try c.transfer(to, transferAmount) returns (bool r) { ok = r; revertedHelper(); } catch { ok = false; }
            assert(ok);
            assert(c.balanceOf(address(this)) == bal - transferAmount);
            assert(c.balanceOf(to) == transferAmount);
        }
    }

    function revertedHelper() private pure {}
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 amount) public {
        // Acquire a balance via the airdrop (fresh contract: caller is whitelisted).
        c.getTokens();
        // Take ownership so burn() is callable from this test contract.
        c.transferOwnership(address(this));
        require(amount > 0 && amount <= c.balanceOf(address(this)));

        uint256 supplyBefore = c.totalSupply();
        uint256 distBefore = c.totalDistributed();
        uint256 balBefore = c.balanceOf(address(this));

        c.burn(amount);

        assert(c.balanceOf(address(this)) == balBefore - amount && c.totalSupply() == supplyBefore - amount && c.totalDistributed() == distBefore - amount);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
