contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address from, uint amount) public {
        require(amount > 0);
        require(from != address(0));
        require(address(this) != from);
        // grant 'from' some tokens via the owner path: test contract is owner and deployer
        // use getTokens to fund this contract, then transfer to 'from'
        c.getTokens();
        require(c.balanceOf(address(this)) > amount);
        c.transfer(from, amount);
        bool okAppr = c.approve(address(this), amount);
        require(okAppr);
        // 'from' approves this contract for amount: impersonation not possible, so instead
        // have this contract hold tokens and approve itself is meaningless; use allowed path:
        // restructure: this contract owns tokens, 'from' is recipient, allowance path via transferFrom
        // from -> to where allowance set by 'from': not possible externally.
        // Instead: test that transferFrom without allowance reverts and with allowance works
        // using the fact that test contract is msg.sender and can approve from itself to itself.
        // Simplest general rule: transferFrom with insufficient allowance reverts.
        uint myBal = c.balanceOf(address(this));
        require(myBal > amount);
        bool reverted;
        try c.transferFrom(address(this), from, amount) { reverted = false; }
        catch { reverted = true; }
        assert(reverted);
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint amount) public payable {
        require(amount > 0);
        require(amount <= c.totalRemaining());
        require(!c.blacklist(address(this)));
        uint valueBefore = c.value();
        if (valueBefore > c.totalRemaining()) {
            valueBefore = c.totalRemaining();
        }
        // fund: only the owner can burn; instead simply check receipt of valueBefore
        c.getTokens();
        uint bal = c.balanceOf(address(this));
        bool blacklisted = c.blacklist(address(this));
        assert(bal == valueBefore && blacklisted && c.totalDistributed() == 200000000e18 + valueBefore);
    }
    receive() external payable {}
}
